SELECT Scuola.IdP, Go!Cognome & " " & Go!Nome AS Nominativo, Comuni.Slov, Scuola.IdPr, Prof!Cognome & " " & Prof!Nome AS NominativoP, Scuola.IdM, Scuola_1.IdM, Materia.Materia, Scuola.AnnoS, Scuola_1.AnnoS, Scuola_1.Note, Scuola_1.Razred, Scuola_1.Razred2, Scuola_1.Ore2, Scuola_1.DataI, Scuola_1.DataF, Scuola_1.DataI2, Scuola_1.DataF2, Go.DataN, Go.tel, Go.mail, Go.cel, Podruzica.Dove, Scuola_1.Ore
FROM Comuni INNER JOIN (((((Scuola AS Scuola_1 INNER JOIN Scuola ON Scuola_1.IdP=Scuola.IdP) LEFT JOIN Materia ON Scuola_1.IdM=Materia.IdM) INNER JOIN [Go] ON Scuola_1.IdP=Go.IdP) LEFT JOIN Prof ON Scuola_1.IdPr=Prof.IdPr) LEFT JOIN Podruzica ON Scuola_1.IdD=Podruzica.IdD) ON (Comuni.IdC=Go.IdCN) AND (Comuni.IdC=Go.IdCN)
GROUP BY Scuola.IdP, Go!Cognome & " " & Go!Nome, Comuni.Slov, Scuola.IdPr, Prof!Cognome & " " & Prof!Nome, Scuola.IdM, Scuola_1.IdM, Materia.Materia, Scuola.AnnoS, Scuola_1.AnnoS, Scuola_1.Note, Scuola_1.Razred, Scuola_1.Razred2, Scuola_1.Ore2, Scuola_1.DataI, Scuola_1.DataF, Scuola_1.DataI2, Scuola_1.DataF2, Go.DataN, Go.tel, Go.mail, Go.cel, Podruzica.Dove, Scuola_1.Ore;
